mapper.select:
SELECT FINPROD_MARKET_ID id, FINPROD_NAME text, FINPROD_ID object FROM FIN_PRODUCT
FINPROD_TYPE2 = #{finprodType2}
AND (FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR FINPROD_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND FINPROD_MARKET_ID = #{initValue}

SELECT FP.FINPROD_ID   FINPRODID,
       FP.TRADE_MARKET TRADEMARKET,
       FP.VDATE        VDATE,
       FP.MDATE        MDATE,
       SEC.PORTFOLIO_ID,
       FTP.TYPE_4  windTypeOne
FROM FIN_PRODUCT FP
INNER JOIN FIN_PRODUCT_TYPE FTP ON FTP.FINPROD_ID=FP.FINPROD_ID
         LEFT JOIN PTL_SEC_POSITION SEC
                   ON SEC.FINPROD_ID = FP.FINPROD_ID
                       AND SEC.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
                       AND SEC.INV_AIM = #{invAim, jdbcType=VARCHAR}
                       AND SEC.HODING_TYPE = #{hodingtype, jdbcType=VARCHAR}
                       AND SEC.SEC_ACCT_ID = #{secacctid, jdbcType=VARCHAR}
                       AND SEC.CDATE = TO_DATE(#{cdate, jdbcType=DATE}, 'yyyy-MM-dd') - 1
WHERE FP.FINPROD_MARKET_ID = #{finprodMarketId, jdbcType=VARCHAR}

SELECT DISTINCT pp.PORTFOLIO_ID id, pp.PORTFOLIO_NAME text
FROM PTL_PORTFOLIO pp LEFT JOIN PTL_SEC_ACCT psa on pp.PORTFOLIO_ID = psa.PORTFOLIO_ID left join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pp.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01'
pp.INVEST_YESORNO = 'Y' AND pp.PORTFOLIO_TYPE = '01' and pp.PORTFOLIO_ID != #{investPortfolioId}
AND (pp.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR pp.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND pp.PORTFOLIO_ID = #{initValue}
AND psa.ACCT_NO = #{secManageAcctId}
AND pp.MDATE > to_date(#{tradeDate},'yyyy-mm-dd')

SELECT DISTINCT B.ACCT_NO as acctNo
FROM PTL_CAPACCT_INFO B,
     STL_CAPACCT_INFO C
WHERE B.PORTFOLIO_ID = #{groupId,jdbcType=VARCHAR}
  AND B.ACCT_TYPE = #{ACCT_TYPE,jdbcType=VARCHAR}
  AND B.CCY = #{ccy,jdbcType=VARCHAR}
  AND B.ACCT_NO = C.ACCT_NO
  AND B.CCY = C.CCY

SELECT DISTINCT P.ACCT_NO id, S.ACCT_NAME text FROM PTL_CAPACCT_INFO P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY = #{ccy}

SELECT PORTFOLIO_NAME
FROM PTL_PORTFOLIO
WHERE PORTFOLIO_ID = #{portfolioId}

select NVL(MARKET_VALUE,0)/SHARE_AMT
from PTL_SEC_VALUTION
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND INV_AIM = #{invAim,jdbcType=VARCHAR}
AND CCY =  #{ccy,jdbcType=VARCHAR}
AND CDATE = to_date(#{tradeDate}, 'yyyy-MM-dd')

select
(SELECT COUNT(1)
  FROM TRD_PRODUCT_DEAL TD
 INNER JOIN TRD_PRODUCT_DEAL_ADD TDA
    ON TD.TRADE_ID = TDA.TRADE_ID
 WHERE TD.INV_AIM = #{turnInvAim,jdbcType=VARCHAR}
   AND TD.TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}
   AND TDA.PORTFOLIO_ID != #{portfolioId,jdbcType=VARCHAR}
   AND TD.CPRICE_AMT = #{unitCprice,jdbcType=DECIMAL}
   AND TD.IS_OUT_TRADE = 'N' AND TD.TRADE_STATUS = '01' AND TD.IS_CANCEL = 'N')
+
(SELECT COUNT(1)
  FROM WFL_TRD_PRODUCT_DEAL WP
 INNER JOIN WFL_TRD_PRODUCT_DEAL_ADD WPA
    ON WP.TRADE_ID = WPA.TRADE_ID
   AND WPA.PORTFOLIO_ID != #{portfolioId,jdbcType=VARCHAR}
   AND WP.TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}
   AND WP.CPRICE_AMT = #{unitCprice,jdbcType=DECIMAL}
   AND WP.IS_OUT_TRADE = 'N') from dual

select count(*)
from (
         select TRADE_ID
         from WFL_TRD_PRODUCT_DEAL
         where TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}
           and INV_AIM = #{invAim}
           and COUNTER_ID = #{portfolioId}
           and FINPROD_ID = #{finprodId}
           and UNIT_CPRICE != #{unitCprice}
           and remark = '债券类资产转入交易'
         union all
         select t1.TRADE_ID
         from WFL_TRD_PRODUCT_DEAL t1
             left join WFL_TRD_PRODUCT_DEAL_ADD t2
         on t1.TRADE_ID=t2.TRADE_ID
         where t1.TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}
           and t1.INV_AIM = #{invAim}
           and t2.PORTFOLIO_ID = #{portfolioId}
           and t1.FINPROD_ID = #{finprodId}
           and t1.UNIT_CPRICE != #{unitCprice}
           and t1.ps='T02'
           and remark != '债券类资产转入交易'
         union all
         select t1.TRADE_ID
         from TRD_PRODUCT_DEAL t1
             left join TRD_PRODUCT_DEAL_ADD t2
         on t1.TRADE_ID=t2.TRADE_ID
         where t1.TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}
           and t1.INV_AIM = #{invAim}
           and t2.PORTFOLIO_ID = #{portfolioId}
           and t1.FINPROD_ID = #{finprodId}
           and t1.UNIT_CPRICE != #{unitCprice}
           AND t1.TRADE_STATUS = '01'
           AND t1.IS_CANCEL = 'N'
           and t1.ps='T02'
     )

select * from
(select SEC_ID finprodId,  NETPRICE valuation
 from MST_BOND_VALUATION_INFO
 where SEC_ID = #{finprodId,jdbcType=VARCHAR}
   and VALUE_SOURCE = #{valueSource,jdbcType=VARCHAR}
   and VALUE_DATE   <  to_date(#{tradeDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
 order by VALUE_DATE desc
)
where rownum = 1
